#![cfg(feature = "usb")]
//! Runs programs generated by `reef_infer::codegen` on an Edge TPU and checks
//! every output byte against the host reference.

use std::sync::Arc;

use reef_infer::codegen::Quant;
use reef_infer::codegen::add::Add;
use reef_infer::codegen::avg_pool::GlobalAvgPool;
use reef_infer::codegen::conv::Conv;
use reef_infer::codegen::elementwise::{self, Requant, SIZE};
use reef_infer::codegen::fc::Fc;
use reef_infer::codegen::pool::MaxPool;
use reef_infer::runner::Device;

fn bytes(seed: &mut u64, n: usize) -> Vec<u8> {
    (0..n)
        .map(|_| {
            *seed ^= *seed << 13;
            *seed ^= *seed >> 7;
            *seed ^= *seed << 17;
            (*seed >> 32) as u8
        })
        .collect()
}

#[tokio::test]
async fn generated_programs_on_tpu() {
    let mut dev = Device::open().await.expect("failed to open device");
    let mut seed = 0x9e3779b97f4a7c15u64;

    // Element-wise requantization, including parameters the compiler would
    // never emit (negative multiplier, nonzero out_zp, asymmetric clamp).
    let q = Quant {
        scale: 0.05,
        zero_point: 128,
    };
    for rq in [
        Requant::from_quant(
            q,
            Quant {
                scale: 0.025,
                zero_point: 0,
            },
            true,
        ),
        Requant {
            in_zp: 128,
            mult: -1.0,
            clamp_min: -128.0,
            clamp_max: 127.0,
            out_zp: 128,
        },
        Requant {
            in_zp: 100,
            mult: 2.5,
            clamp_min: -10.0,
            clamp_max: 40.7,
            out_zp: 50,
        },
    ] {
        let model = Arc::new(elementwise::build(&rq, q, q, true).unwrap().into_model());
        let x = bytes(&mut seed, SIZE);
        let loaded = dev.load_params(model).await.unwrap();
        let got = dev.run_inference(&loaded, x.clone()).await.unwrap();
        let want: Vec<u8> = x.iter().map(|&v| rq.apply(v)).collect();
        assert!(got == want, "{rq:?}");
    }

    // Fully connected layers with random weights: one tile, K spread over
    // several input tiles (a partial last one for 784 / 1000), N over
    // several compute tiles, and N padded to 16 (the MNIST layers: 784 x
    // 128 ReLU, 128 x 10).
    for (k, n, relu) in [
        (64, 64, false),
        (8, 16, true),
        (40, 48, false),
        (128, 64, false),
        (784, 128, true),
        (128, 10, false),
        (1000, 64, false),
        (256, 256, true),
        (64, 1024, false),
        (64, 4, false),
        // 128 / 256 B per input tile (the MNIST CNN's dense layer: 3136 x 10)
        (2048, 64, false),
        (3136, 10, false),
        (4096, 64, true),
    ] {
        let w = bytes(&mut seed, n * k);
        let fc = Fc {
            k,
            n,
            weights: w.iter().map(|&b| b as i8).collect(),
            w_scale: (0..n).map(|i| 0.003 + 0.0002 * i as f32).collect(),
            bias: (0..n).map(|i| 250 * i as i32 - 5000).collect(),
            input: Quant {
                scale: 0.03,
                zero_point: 120,
            },
            // wider sums for larger K, so the outputs do not all saturate
            output: Quant {
                scale: 0.3 * (k as f32 / 64.0).sqrt(),
                zero_point: 130,
            },
            relu,
        };
        let loaded = dev
            .load_params(Arc::new(fc.build().unwrap()))
            .await
            .unwrap();
        for _ in 0..4 {
            let x = bytes(&mut seed, k);
            let got = dev.run_inference(&loaded, x.clone()).await.unwrap();
            assert_eq!(got, fc.reference(&x), "fc K={k} N={n} relu={relu}");
        }
    }

    // Element-wise adds (two input layers), including ResNet-8's shapes and
    // scale ratios no corpus model has (weights from the fraction search).
    let q = |scale: f32, zero_point: i32| Quant { scale, zero_point };
    for (h, w, c, qa, qb, qo, relu) in [
        (
            16,
            16,
            32,
            q(0.0313, 128),
            q(0.0313, 128),
            q(0.0627, 127),
            false,
        ),
        (32, 32, 16, q(0.0370, 0), q(0.1254, 122), q(0.0656, 0), true),
        (
            16,
            16,
            32,
            q(0.0649, 106),
            q(0.0720, 119),
            q(0.0380, 0),
            true,
        ),
        (
            16,
            16,
            64,
            q(0.0857, 54),
            q(0.1155, 105),
            q(0.0674, 0),
            true,
        ),
        (
            32,
            32,
            64,
            q(0.0078, 128),
            q(0.0314, 127),
            q(0.0391, 128),
            false,
        ),
    ] {
        let add = Add {
            height: h,
            width: w,
            c,
            a: qa,
            b: qb,
            output: qo,
            relu,
        };
        let model = Arc::new(add.build().unwrap().into_model());
        let loaded = dev.load_params(model).await.unwrap();
        for _ in 0..2 {
            let (x, y) = (bytes(&mut seed, h * w * c), bytes(&mut seed, h * w * c));
            let got = dev
                .run_inference(&loaded, [x.clone(), y.clone()].concat())
                .await
                .unwrap();
            assert!(
                got == add.reference(&x, &y),
                "add {h}x{w}x{c} weights {:?}",
                add.weights()
            );
        }
    }

    // 2x2 max pools, including the MNIST CNN's (32x32x32, 16x16x64).
    for (height, width, c, zp) in [
        (16, 16, 32, 128),
        (32, 32, 32, 0),
        (16, 16, 64, 0),
        (32, 16, 32, 37),
        (16, 16, 128, 250),
    ] {
        let pool = MaxPool {
            height,
            width,
            c,
            quant: Quant {
                scale: 0.05,
                zero_point: zp,
            },
        };
        let model = Arc::new(pool.build().unwrap().into_model());
        let loaded = dev.load_params(model).await.unwrap();
        for _ in 0..2 {
            let x = bytes(&mut seed, height * width * c);
            let got = dev.run_inference(&loaded, x.clone()).await.unwrap();
            assert!(
                got == pool.reference(&x),
                "pool {height}x{width}x{c} zp {zp}"
            );
        }
    }

    // Global 8x8x64 average pool: the compiler's form (centre = zero point,
    // mult 1 / 64) and TFLite's exact rounding (int8 and uint8), on random
    // images, the extremes, and images whose every channel sum is a tie.
    let q = Quant {
        scale: 0.03,
        zero_point: 127,
    };
    let ties: Vec<u8> = (0..64 * 64)
        .map(|i| (4 * (i % 64) + (i / 64) % 2) as u8)
        .collect();
    for pool in [
        GlobalAvgPool {
            height: 8,
            width: 8,
            c: 64,
            center: 127,
            mult: 1.0 / 64.0,
            quant: q,
        },
        GlobalAvgPool::tflite(8, 8, 64, q, true).unwrap(),
        GlobalAvgPool::tflite(8, 8, 64, q, false).unwrap(),
    ] {
        let model = Arc::new(pool.build().unwrap().into_model());
        let loaded = dev.load_params(model).await.unwrap();
        let mut inputs = vec![vec![0u8; 4096], vec![255u8; 4096], ties.clone()];
        inputs.extend((0..3).map(|_| bytes(&mut seed, 4096)));
        for x in inputs {
            let got = dev.run_inference(&loaded, x.clone()).await.unwrap();
            assert!(
                got == pool.reference(&x),
                "average pool centre {} mult {}",
                pool.center,
                pool.mult
            );
        }
    }

    // Convolutions with random weights: 1x1, and 3x3 (halo exchange, zero
    // point padding at the image border).
    for (k, stride, height, width, cin, cout, relu, in_zp, out_zp) in [
        (1, 1, 16, 16, 16, 32, false, 127, 131),
        (1, 1, 16, 16, 16, 32, true, 100, 0),
        (3, 1, 16, 16, 16, 32, false, 127, 130),
        (3, 1, 16, 16, 16, 16, true, 3, 0),
        (3, 1, 16, 16, 16, 8, false, 250, 20),
        (3, 1, 16, 16, 32, 32, false, 128, 120),
        (3, 1, 16, 16, 64, 16, true, 60, 0),
        (3, 1, 16, 16, 128, 8, false, 140, 200),
        (3, 1, 16, 16, 128, 32, false, 128, 128),
        (3, 1, 16, 16, 3, 32, false, 127, 128),
        (3, 1, 16, 16, 3, 16, true, 0, 0),
        (3, 1, 16, 16, 1, 8, false, 200, 50),
        (3, 1, 16, 16, 4, 32, false, 90, 140),
        (1, 2, 16, 16, 16, 32, false, 127, 120),
        (3, 2, 16, 16, 16, 32, false, 128, 130),
        (3, 2, 16, 16, 3, 16, true, 10, 0),
        (3, 2, 16, 16, 64, 8, false, 128, 60),
        // Cout 64 (1 KiB of output per tile): the MNIST CNN's second conv
        (3, 1, 16, 16, 32, 64, true, 0, 0),
        (3, 1, 16, 16, 64, 64, false, 128, 128),
        (3, 1, 16, 16, 128, 64, false, 128, 100),
        // wider images: superpixels of width / 16 pixels
        (1, 1, 16, 32, 16, 32, false, 127, 128),
        (3, 1, 16, 32, 16, 32, false, 120, 128),
        (3, 1, 16, 64, 16, 16, true, 128, 0),
        (3, 2, 16, 64, 32, 16, false, 100, 150),
        // taller images: bands of 4 rows per tile
        (3, 1, 32, 16, 16, 32, false, 128, 128),
        (3, 2, 64, 32, 16, 32, false, 120, 130),
        (3, 1, 64, 64, 16, 8, true, 128, 0),
        // the MNIST CNN's first conv (28x28 padded to 32, Cin 1 as 16)
        (3, 1, 32, 32, 16, 32, true, 0, 0),
        // ResNet-8: 32x32 stage, stride-2 downsampling with 1x1 shortcuts
        (3, 1, 32, 32, 16, 16, true, 0, 0),
        (3, 1, 32, 32, 16, 16, false, 0, 122),
        (3, 2, 32, 32, 16, 32, true, 0, 0),
        (1, 2, 32, 32, 16, 32, false, 0, 106),
        (3, 2, 16, 16, 32, 64, true, 0, 0),
        (1, 2, 16, 16, 32, 64, false, 0, 54),
        (1, 1, 16, 16, 32, 64, false, 128, 128),
    ] {
        let w = bytes(&mut seed, cout * k * k * cin);
        let conv = Conv {
            cin,
            cout,
            k,
            stride,
            width,
            height,
            weights: w.iter().map(|&b| b as i8).collect(),
            w_scale: (0..cout)
                .map(|i| (0.0007 + 0.0001 * i as f32) * 16.0 / cin as f32)
                .collect(),
            bias: (0..cout).map(|i| 300 * i as i32 - 4000).collect(),
            input: Quant {
                scale: 0.03,
                zero_point: in_zp,
            },
            output: Quant {
                scale: 0.2,
                zero_point: out_zp,
            },
            relu,
        };
        let loaded = dev
            .load_params(Arc::new(conv.build().unwrap()))
            .await
            .unwrap();
        for _ in 0..3 {
            let x = bytes(&mut seed, height * width * cin);
            let got = dev.run_inference(&loaded, x.clone()).await.unwrap();
            let want = conv.reference(&x);
            let bad = got.iter().zip(&want).filter(|(a, b)| a != b).count();
            assert!(
                bad == 0,
                "conv k={k} s={stride} {height}x{width} Cin={cin} Cout={cout} relu={relu} zp {in_zp}/{out_zp}: {bad}/{} wrong",
                want.len()
            );
        }
    }

    // Cached parameters at their own wide addresses coexist: load an FC
    // on 2 tiles, a conv and a small FC one after the other, then run all.
    let fc_a = Fc {
        k: 784,
        n: 128,
        weights: bytes(&mut seed, 784 * 128)
            .iter()
            .map(|&b| b as i8)
            .collect(),
        w_scale: vec![0.004; 128],
        bias: (0..128).map(|i| 100 * i).collect(),
        input: Quant {
            scale: 0.03,
            zero_point: 120,
        },
        output: Quant {
            scale: 1.0,
            zero_point: 128,
        },
        relu: false,
    };
    let fc_b = Fc {
        k: 128,
        n: 10,
        weights: bytes(&mut seed, 1280).iter().map(|&b| b as i8).collect(),
        w_scale: vec![0.004; 10],
        bias: vec![0; 10],
        ..fc_a.clone()
    };
    let conv = Conv {
        cin: 32,
        cout: 32,
        k: 3,
        stride: 1,
        width: 16,
        height: 16,
        weights: bytes(&mut seed, 32 * 9 * 32)
            .iter()
            .map(|&b| b as i8)
            .collect(),
        w_scale: vec![0.0004; 32],
        bias: vec![-2000; 32],
        input: Quant {
            scale: 0.03,
            zero_point: 100,
        },
        output: Quant {
            scale: 0.2,
            zero_point: 120,
        },
        relu: false,
    };
    let (ua, uc) = (fc_a.wide_units(), conv.wide_units());
    let la = dev
        .load_params(Arc::new(fc_a.build_at(0).unwrap()))
        .await
        .unwrap();
    let lc = dev
        .load_params(Arc::new(conv.build_at(ua).unwrap()))
        .await
        .unwrap();
    let lb = dev
        .load_params(Arc::new(fc_b.build_at(ua + uc).unwrap()))
        .await
        .unwrap();
    let x = bytes(&mut seed, 784);
    assert_eq!(
        dev.run_inference(&la, x.clone()).await.unwrap(),
        fc_a.reference(&x)
    );
    let x = bytes(&mut seed, 16 * 16 * 32);
    assert!(dev.run_inference(&lc, x.clone()).await.unwrap() == conv.reference(&x));
    let x = bytes(&mut seed, 128);
    assert_eq!(
        dev.run_inference(&lb, x.clone()).await.unwrap(),
        fc_b.reference(&x)
    );

    chained(&mut dev, &mut seed).await;
    loopback(&mut dev).await;
}

/// Two convs in one program with the activation kept on chip: the first
/// writes into the second's padded patch at narrow 0x1000.
async fn chained(dev: &mut Device, seed: &mut u64) {
    use reef_infer::codegen::chain::splice;
    use reef_infer::codegen::conv::Io;
    use reef_infer::executable_generated::platforms::darwinn::ExecutableType;
    use reef_infer::model::{ExecInfo, TfliteModel};
    let conv = |seed: &mut u64, cin: usize, cout: usize, zp: (i32, i32), relu| Conv {
        cin,
        cout,
        k: 3,
        stride: 1,
        width: 16,
        height: 16,
        weights: bytes(seed, cout * 9 * cin)
            .iter()
            .map(|&b| b as i8)
            .collect(),
        w_scale: vec![0.0007 * 16.0 / cin as f32; cout],
        bias: (0..cout).map(|i| 300 * i as i32 - 4000).collect(),
        input: Quant {
            scale: 0.03,
            zero_point: zp.0,
        },
        output: Quant {
            scale: 0.2,
            zero_point: zp.1,
        },
        relu,
    };
    let a = conv(seed, 16, 32, (100, 0), true);
    let b = conv(seed, 32, 16, (0, 130), false);
    let ua = a.wide_units();
    for (c, base) in [(&a, 0), (&b, ua)] {
        dev.load_params(Arc::new(c.build_at(base).unwrap()))
            .await
            .unwrap();
    }
    let pa = a
        .chain_program(
            0,
            Io {
                output_to: Some((0x1000, b.input_patch())),
                ..Io::default()
            },
        )
        .unwrap();
    let pb = b
        .chain_program(
            ua,
            Io {
                input_at: Some(0x1000),
                ..Io::default()
            },
        )
        .unwrap();
    let (mut ea, mut eb) = (a.build().unwrap(), b.build().unwrap());
    let model = TfliteModel {
        executables: vec![ExecInfo {
            exec_type: ExecutableType::EXECUTION_ONLY,
            parameters: vec![],
            instruction_chunks: vec![splice(&[pa, pb]).unwrap()],
            input_layers: ea.executables[0].input_layers.drain(..).collect(),
            output_layers: eb.executables[0].output_layers.drain(..).collect(),
            scratch_size_bytes: 0,
        }],
    };
    let loaded = dev.load_params(Arc::new(model)).await.unwrap();
    for _ in 0..3 {
        let x = bytes(seed, 4096);
        let got = dev.run_inference(&loaded, x.clone()).await.unwrap();
        assert!(got == b.reference(&a.reference(&x)), "chained conv -> conv");
    }
}

/// Generated loopback: tile `SRC` -> scalar memory -> all 16 tiles. The
/// other tiles hold zeros; each tile returns the 512 B at a received unit's
/// wide address, and two passes recover which source byte landed where.
async fn loopback(dev: &mut Device) {
    use reef_infer::codegen::elementwise::{SHAPE, bcast_unit_addr};
    use reef_infer::isa;

    const SRC: usize = 6;
    let id = Requant {
        in_zp: 0,
        mult: 1.0,
        clamp_min: 0.0,
        clamp_max: 255.0,
        out_zp: 0,
    };
    let q = Quant {
        scale: 1.0,
        zero_point: 0,
    };
    let (_, nx, nz) = SHAPE;
    // y-x-z index -> offset in tile `t`'s 512 B (rows of 4 pixels x 32 B)
    let local = |i: usize, t: usize| -> Option<usize> {
        let (y, x) = (i / nz / nx, i / nz % nx);
        let (ty, tx) = (4 * (t / 4), 4 * (t % 4));
        (y / 4 * 4 == ty && x / 4 * 4 == tx).then(|| ((y - ty) * 4 + x - tx) * nz + i % nz)
    };
    for u in [0, 2, 3, 11, 12, 15, 23] {
        let mut got = [vec![0u8; SIZE], vec![0u8; SIZE]];
        for (pass, out) in got.iter_mut().enumerate() {
            let x: Vec<u8> = (0..SIZE)
                .map(|i| match local(i, SRC) {
                    Some(l) if pass == 0 => (l % 255 + 1) as u8,
                    Some(l) => (l / 255 + 1) as u8,
                    None => 0,
                })
                .collect();
            let mut m = elementwise::build_broadcast(&id, q, q, SRC)
                .unwrap()
                .into_model();
            // point the 16 host producers at unit u
            let c = &mut m.executables[0].instruction_chunks[0];
            let mut word = 0;
            for ins in isa::split(&c.bitstream.clone()).unwrap() {
                let mut d = ins.decode().unwrap();
                if d.layout.name == "ringProducer" && d.get("r0_id") == Some(0x51) {
                    d.set("addr", bcast_unit_addr(u)).unwrap();
                    for (j, w) in d.encode().unwrap().iter().enumerate() {
                        c.bitstream[(word + j) * 16..(word + j + 1) * 16]
                            .copy_from_slice(&w.to_le_bytes());
                    }
                }
                word += ins.words.len();
            }
            let loaded = dev.load_params(Arc::new(m)).await.unwrap();
            *out = dev.run_inference(&loaded, x).await.unwrap();
        }
        for t in 0..16 {
            // first 16 B of tile t's output = unit u of tile SRC
            let src: Vec<usize> = (0..SIZE)
                .filter(|&i| local(i, t).is_some_and(|l| l < 16))
                .map(|i| (got[1][i] as usize - 1) * 255 + got[0][i] as usize - 1)
                .collect();
            assert_eq!(
                src,
                (16 * u..16 * u + 16).collect::<Vec<_>>(),
                "tile {t} unit {u}"
            );
        }
    }
}
